(()=>{'use strict';
const $=id=>document.getElementById(id),sizes=[.6,.9,1.2,1.8,2.4],section=document.createElement('section');
section.id='dishSizing';section.innerHTML=`<div class="dish-heading"><div><span class="dish-eyebrow">ANTENNA PLANNING</span><h2>ประเมินและแนะนำขนาดจาน</h2><p>เลือกเป้าหมายบริการ แล้วเปรียบเทียบจานขนาดเดียวกันทั้งสองสถานี</p></div><span class="dish-tag">A ↔ B</span></div>
<fieldset class="dish-targets"><legend>1. Target availability</legend><label><input type="radio" name="dishGroup" value="99.9xxx" checked><span><b>99.9xxx %</b><small>ตั้งแต่ 99.9000 ถึง 99.9899%</small></span></label><label><input type="radio" name="dishGroup" value="99.99xx"><span><b>99.99xx %</b><small>ตั้งแต่ 99.9900 ถึง 99.9999%</small></span></label></fieldset>
<div class="fields dish-fields"><label>Target ที่ต้องการ (%)<input id="dishTarget" type="number" value="99.9000" step="0.0001" min="99.9" max="99.9899"></label><label>Modulation ที่ต้องการรักษา<select id="dishMode"><option value="">คำนวณลิงก์เพื่อโหลดโหมด</option></select></label><label>แหล่ง Gain จาน<select id="dishGain"><option value="estimate">ประมาณจากจานอ้างอิง A / B</option><option value="vendor">กรอก Gain จากผู้ผลิตแต่ละขนาด</option></select></label></div>
<p id="dishAllowance" class="note"></p><p id="dishReference" class="note">จานอ้างอิงใช้ขนาดและ gain ของสถานี A / B ในผลคำนวณลิงก์</p>
<div id="dishVendor" hidden><label>รุ่นจาน / เอกสารอ้างอิง (ระบุแต่ละขนาดและหน้าตาราง)<input id="dishSource" type="text" placeholder="รุ่นจาน · ชื่อเอกสาร · หน้า · ความถี่" style="display:block;width:100%;margin-top:8px"></label><div class="dish-table"><table><thead><tr><th>ขนาดจาน A / B (m)</th><th>Gain A (dBi)</th><th>Gain B (dBi)</th></tr></thead><tbody>${sizes.map((d,i)=>`<tr><td>${d.toFixed(2)}</td><td><input id="dishGa${i}" type="number" step="0.01" aria-label="Gain A จาน ${d} เมตร"></td><td><input id="dishGb${i}" type="number" step="0.01" aria-label="Gain B จาน ${d} เมตร"></td></tr>`).join('')}</tbody></table></div><p class="note">กรอก gain ที่ความถี่ใช้งานจริง ค่าที่กรอกใช้สำหรับการประเมินชุดนี้เท่านั้น</p></div>
<p class="note">2. ประเมินขนาด 0.60, 0.90, 1.20, 1.80 และ 2.40 เมตร · ใช้ TX/RX threshold และ degradation ของโหมดที่เลือก · ต้องผ่าน LOS/Fresnel และมีข้อมูลภูมิอากาศครบ</p>
<div class="dish-actions"><button id="dishAnalyze" type="button">วิเคราะห์ขนาดจาน</button><button id="dishReport" type="button" disabled>เปิดรายงาน / Export PDF</button></div><p id="dishStatus" role="status">กรอกข้อมูลแล้วคำนวณลิงก์ก่อนประเมินขนาดจาน</p><div id="dishOutput"></div>`;
$('mwForm').after(section);
let base=null,path=null;
const number=id=>$(id).value.trim()===''?null:Number($(id).value);
function options(){return {group:section.querySelector('[name="dishGroup"]:checked').value,target:number('dishTarget'),modeIndex:$('dishMode').value===''?-1:Number($('dishMode').value),gainSource:$('dishGain').value,source:$('dishSource').value,sizes:sizes.map((diameter,i)=>({diameter,gainA:number('dishGa'+i),gainB:number('dishGb'+i)}))}}
function save(){try{localStorage.setItem('mw-dish-settings',JSON.stringify({values:Object.fromEntries([...section.querySelectorAll('input[id],select[id]')].map(e=>[e.id,e.value])),group:options().group}))}catch{}}
function describe(){const o=options();$('dishVendor').hidden=o.gainSource!=='vendor';$('dishTarget').min=o.group==='99.9xxx'?'99.9':'99.99';$('dishTarget').max=o.group==='99.9xxx'?'99.9899':'99.9999';$('dishAllowance').textContent=MWDish.targetValid(o.group,o.target)?'เวลาหยุดจากการแพร่คลื่นที่ยอมให้ได้: '+((100-o.target)*5256).toFixed(2)+' นาที/ปี ต่อทิศทาง/โพลาไรซ์':'กรอกค่าเป้าหมายให้ตรงช่วงที่เลือก (ทศนิยมไม่เกิน 4 ตำแหน่ง)'}
function assess(){describe();if(!base)return;const o=MWDish.evaluate(base,path,options());base.dishSizing=o;$('dishOutput').innerHTML=MWDish.html(o);$('dishReport').disabled=false;$('dishStatus').textContent=o.errors.length?'ยังประเมินไม่ได้ · ตรวจข้อมูลที่ระบุด้านล่าง':o.recommendation!==null?'วิเคราะห์แล้ว · แนบคำแนะนำในรายงานเรียบร้อย':'วิเคราะห์แล้ว · ยังไม่มีขนาดที่ยืนยันผ่านได้ ดูเหตุผลรายขนาด'}
function invalidate(){if(base)delete base.dishSizing;base=null;path=null;$('dishOutput').innerHTML='';$('dishReport').disabled=true;$('dishStatus').textContent='ข้อมูลลิงก์ยังไม่ได้คำนวณ หรือมีการแก้ไข · คำนวณลิงก์ใหม่เพื่อประเมินขนาดจาน'}
section.addEventListener('input',e=>{if(e.target.name==='dishGroup')$('dishTarget').value=e.target.value==='99.9xxx'?'99.9000':'99.9900';save();describe();assess()});
$('dishAnalyze').onclick=()=>{if(base)assess();else{$('dishStatus').textContent='กำลังคำนวณลิงก์ก่อนวิเคราะห์ขนาดจาน…';$('mwForm').requestSubmit()}};
$('dishReport').onclick=()=>$('print').click();
try{const v=JSON.parse(localStorage.getItem('mw-dish-settings')||'null');if(v){for(const [id,value] of Object.entries(v.values||{})){const el=$(id);if(el&&id!=='dishMode')el.value=value}for(const el of section.querySelectorAll('[name="dishGroup"]'))el.checked=el.value===v.group;if(!section.querySelector('[name="dishGroup"]:checked'))section.querySelector('[name="dishGroup"]').checked=true}}catch{}
describe();
globalThis.MWDishUI={invalidate,onCalculated(c,r){const previous=$('dishMode').selectedOptions[0]?.textContent;base=c;path=r;const list=MWDish.modes(c);$('dishMode').replaceChildren(...list.map((m,i)=>new Option(m.name+' · '+m.capacity+' Mbps',String(i))));const idx=[...$('dishMode').options].findIndex(o=>o.textContent===previous);$('dishMode').selectedIndex=idx>=0?idx:0;$('dishReference').textContent='จานอ้างอิง A: '+c.a.diameter+' m / '+c.a.gain+' dBi · B: '+c.b.diameter+' m / '+c.b.gain+' dBi ที่ '+c.freq+' GHz · ค่า gain ประมาณสมมติประสิทธิภาพเท่าเดิม';assess()}};
})();
